import {characterEquipment} from './characters.js';
import {sculptUnit} from './sculpted-style.js';
import {decorateBuilding,decorateUnit} from './visual-style.js';
import * as T from './vendor/three.module.js';
import {buildingModel,unitModel,part} from './models-3d.js';
import {applyBuildingLevel} from './building-levels.js';
import {BUILDINGS,UNITS,NPCS,CIVILIZATIONS} from './design-data.js';
const P=Math.PI;
export function designBuilding(id,era,level,M,species='human'){const s=BUILDINGS[id];if(!s)throw Error('Edificio desconocido');if(!s.expansion){const model=buildingModel(id,era,level,s.size,M);styleBuilding(model,species,M);return model;}const g=new T.Group(),modern=era>=12,mat=modern?M.metal:M.wood,wall=modern?M.metal:M.plaster,size=s.size,e=size*.38;
 const b=(m,x,y,z,a,h,c,rx=0,ry=0,rz=0)=>part(g,'box',m,x,y,z,a,h,c,rx,ry,rz),c=(m,x,y,z,r,h)=>part(g,'cylinder',m,x,y,z,r,h,r),roof=(x,y,z,a,d)=>part(g,'roof',modern?M.roofdark:M.roof,x,y,z,a,a*.68,d),house=(w=1.1,d=.8,h=.75)=>{b(M.stone,0,.06,0,w+.12,.12,d+.12);b(wall,0,h/2+.13,0,w,h,d);roof(0,h+.13,0,w+.2,d+.18);b(M.darkwood,0,.43,d/2+.02,.3,.56,.03);},crate=(x,z)=>{b(M.wood,x,.2,z,.34,.36,.34);b(M.iron,x,.22,z+.18,.35,.03,.025);},tank=(x,z,r=.3)=>{c(M.metal,x,.4,z,r,.74);c(M.iron,x,.8,z,r*1.04,.06);};
 const shape=s.shape;g.userData.designId=id;
 if(['tower','lighthouse','signal','radar','shield'].includes(shape)){c(shape==='lighthouse'?M.plaster:M.stone,0,.9,0,.37,1.7);c(mat,0,1.77,0,.45,.16);if(shape==='lighthouse'){c(M.glass,0,1.98,0,.3,.35);part(g,'cone',M.roof,0,2.25,0,.43,.3,.43);}else if(shape==='radar'||shape==='signal'){c(M.iron,0,2.13,0,.035,.6);part(g,'ball',M.cloth,0,2.52,0,.48,.15,.48,.45);b(M.glow,0,2.35,.1,.08,.06,.08);}else{part(g,'ring',shape==='shield'?M.glow:M.iron,0,2.08,0,.48,.48,.48,P/2);b(M.iron,0,1.98,.4,.14,.15,.8);}}
 else if(['bunker','ballista','cannon','antiair','coastal','munitions'].includes(shape)){b(M.stone,0,.25,0,1.5,.5,1.4);b(M.darkwood,0,.3,.71,.5,.23,.025);b(M.iron,0,.57,0,1.7,.16,1.55);if(shape==='munitions'){for(const x of[-.45,0,.45]){b(M.wood,x,.8,0,.3,.32,.5);b(M.iron,x,.82,.26,.32,.04,.025);}}else{c(M.iron,0,.77,0,.3,.3);for(const x of shape==='antiair'?[-.18,.18]:[0])b(shape==='ballista'?M.wood:M.iron,x,1.02,.45,.12,.13,1.15,-.3);if(shape==='ballista')b(M.wood,0,.99,.45,1,.08,.08);}}
 else if(['station','freightterminal','cargoharbor','cargoterminal','hangar','shipwright','bridgeyard'].includes(shape)){b(M.stone,0,.06,0,size*.9,.1,size*.82);b(wall,-.45,.5,-.3,.85,.9,1.05);roof(-.45,1.01,-.3,1.08,1.2);if(shape==='hangar'||shape==='cargoterminal'){b(M.black,.49,.5,-.15,.7,.8,.8);part(g,'cylinder',M.iron,.49,.87,-.15,.62,.87,.62,P/2);b(M.roofdark,.35,.1,.65,1.7,.06,.5);}else{for(const x of[-.6,.6])b(M.iron,x,.8,.6,.08,1.5,.08);b(M.iron,0,1.56,.6,1.55,.12,.13);c(M.iron,.35,1.2,.6,.025,.7);crate(-.8,.65);crate(.6,-.7);}if(shape==='station'){for(const x of[.2,.65])b(M.iron,x,.14,0,.04,.04,size*.85);for(let i=0;i<8;i++)b(M.darkwood,.43,.1,-1+i*.27,.7,.05,.1);}if(shape==='shipwright'||shape==='cargoharbor'){for(let i=0;i<7;i++)b(M.wood,-.6+i*.2,.12,.9,.16,.06,.6);}}
 else if(['fueltank','sewage','foundry','workshop','smithy','maintenance','firestation'].includes(shape)){house(1.25,.9,.65);if(shape==='fueltank'||shape==='sewage'){tank(-.6,.4);tank(.6,.3,.23);b(M.iron,0,.35,.55,1.3,.08,.08);}else{c(M.stone,-.5,1.16,-.3,.14,1.45);b(M.black,.2,.4,.47,.58,.5,.03);if(shape==='smithy'||shape==='foundry')b(M.red,.2,.27,.49,.4,.14,.02);for(const x of[-.6,.6])crate(x,.65);if(shape==='firestation')c(M.water,.6,.44,.3,.24,.65);}}
 else if(['granary','mill','bakery','sawmill','carpenter','stable','caravan','livestock','fishery','quarry','lodge'].includes(shape)){house(shape==='stable'?1.45:1.1,shape==='granary'?1.2:.8,.7);if(shape==='mill'){const hub=new T.Group();hub.position.set(0,1.1,.6);for(let i=0;i<4;i++){const a=i*P/2;part(hub,'box',M.wood,Math.cos(a)*.42,Math.sin(a)*.42,0,.8,.07,.05,0,0,a);}g.add(hub);g.userData.rotor=hub;}else if(shape==='sawmill'||shape==='carpenter'){for(let i=0;i<3;i++)part(g,'cylinder',M.wood,-.6+i*.18,.2,.65,.09,1,.09,P/2);part(g,'ring',M.iron,.45,.65,.5,.29,.29,.29,P/2);}else if(shape==='stable'||shape==='livestock'||shape==='caravan'){for(const x of[-.7,.7])for(let i=0;i<4;i++)b(M.wood,x,.28,.1+i*.2,.05,.55,.05);for(const x of[-.7,.7])b(M.wood,x,.4,.45,.045,.04,.85);b(M.wheat,.35,.2,.62,.35,.32,.35);}else if(shape==='granary'){for(const x of[-.7,.7])c(M.wood,x,.5,.2,.18,.9);}else if(shape==='quarry'){part(g,'rock',M.cliff,.4,.3,.5,.6,.45,.5);b(M.wood,-.65,.85,.6,.08,1.6,.08);b(M.wood,-.22,1.57,.6,1,.08,.08);}else if(shape==='fishery'){for(let i=0;i<5;i++)b(M.wood,-.5+i*.25,.08,.7,.2,.07,.55);part(g,'ring',M.cloth,0,.85,.65,.4,.4,.4,P/2);}else if(shape==='bakery')c(M.stone,.48,.8,-.1,.15,1.5);else crate(.6,.6);}
 else{house(1.2,.95,.85);for(const x of[-.55,.55])c(M.stone,x,.5,.65,.06,.85);b(mat,0,.99,.62,1.4,.1,.4);if(['surveyor','geology','engineering'].includes(shape)){for(const x of[-.15,.15])b(M.wood,x,.37,.7,.04,.65,.04,0,0,x*.8);c(M.gold,0,.75,.7,.2,.04);b(M.cloth,.4,.41,.55,.35,.02,.24);}else if(shape==='archive'){for(let i=0;i<5;i++)b(i%2?M.blue:M.wood,-.5+i*.2,.38,.63,.13,.4,.13);}else if(shape==='clinic'){b(M.cloth,0,.93,.5,.48,.3,.025);b(M.blue,0,.93,.53,.32,.06,.02);}else{crate(-.7,.5);b(M.cloth,.62,.3,.4,.28,.025,.4);}}
 decorateBuilding(g,id,era,level,size,M,part);applyBuildingLevel(g,M,id,era,level,size,part);styleBuilding(g,species,M);return g;
}
export function designUnit(id,era,level,M,enemy=false,species='human'){const s=UNITS[id]||NPCS.find(n=>n.id===id);if(!s)throw Error('Unidad desconocida');const type=s.model||id;let g=unitModel(type,M,enemy,era,species);if(['wagon','freighttrain','submarine'].includes(id)){g=transportModel(id,M);decorateUnit(g,id,M,part,era);sculptUnit(g,id,M,part);}g.userData.designId=id;const model=s.id;if(model==='packhorse'){const person=g.userData.joints.body;if(person)person.visible=false;for(const x of[-.27,.27])part(g,'box',M.wood,x,.75,-.15,.18,.3,.45);}if(model==='truck'){part(g,'box',M.wood,0,.68,-.12,.72,.34,.95);if(model==='wagon')part(g,'box',M.cloth,0,1.03,-.15,.8,.06,1.05);}if(model==='oceanresearch'){part(g,'cylinder',M.cloth,.3,1.15,-.3,.04,1.4,.04);part(g,'ball',M.cloth,.3,1.9,-.3,.23,.23,.23);}if(NPCS.some(n=>n.id===id)||['surveyor','engineer','medic'].includes(id))equipCivilian(g,id,M);applyEquipment(g,level,M);return g;}
export function designCivilization(id,era,level,M){const s=CIVILIZATIONS[id];const g=buildingModel(s.model,era,level,2,M);g.userData.designId=id;if(id==='sylvan'){for(const x of[-.8,.8])part(g,'ball',M.leaf,x,1.15,-.3,.4,.5,.35);}if(id==='stonekin'){for(const x of[-.7,.7])part(g,'rock',M.cliff,x,.6,0,.42,.85,.6);}if(id==='thalass'){for(const x of[-.7,.7])part(g,'cylinder',M.wood,x,-.25,.5,.07,.8,.07);part(g,'box',M.cloth,0,1.6,-.6,1.1,.7,.025);}if(id==='synthetic'){for(const x of[-.6,.6])part(g,'box',M.metal,x,1.25,0,.24,.45,.35);}if(id==='astral')part(g,'ring',M.glow,0,1.7,0,.9,.9,.9,Math.PI/2);return g;}

function transportModel(id,M){const g=new T.Group(),joints={wheels:[]};g.userData={type:id,joints};const b=(m,x,y,z,w,h,d)=>part(g,'box',m,x,y,z,w,h,d);if(id==='submarine'){part(g,'ball',M.iron,0,.32,0,.42,.35,1.45);b(M.iron,0,.7,-.2,.3,.5,.45);part(g,'cylinder',M.iron,0,1.05,-.2,.04,.45,.04);b(M.metal,0,.38,-1.2,.8,.05,.3);b(M.metal,0,.58,-1.2,.05,.5,.3);return g;}const train=id==='freighttrain',mat=train?M.iron:M.wood;b(mat,0,.46,0,.83,.2,train?2.6:1.4);if(train){part(g,'cylinder',M.iron,0,.78,.45,.32,1.4,.32,Math.PI/2);b(M.blue,0,1,-.7,.78,.9,.7);b(M.roofdark,0,1.49,-.7,.9,.1,.85);part(g,'cylinder',M.black,0,1.18,.8,.09,.6,.09);b(M.glass,0,1.16,-.34,.5,.24,.025);}else{b(M.wood,0,.78,-.1,.76,.44,1.2);for(const x of[-.4,.4])b(M.wood,x,.96,-.1,.05,.32,1.2);b(M.cloth,0,1.14,-.1,.85,.06,1.3);b(M.wood,0,.3,1.1,.1,.1,.85);}for(const x of[-.49,.49])for(const z of train?[-1,-.4,.4,1]:[-.5,.5])joints.wheels.push(part(g,'cylinder',M.black,x,.28,z,train?.2:.3,.1,train?.2:.3,0,0,Math.PI/2));return g;}
function equipCivilian(g,id,M){const j=g.userData.joints;if(j?.tool&&id!=='builder'){j.tool.visible=false;j.tool=null;}const arm=(j?.hero?j.rightElbow:j?.rightArm)||g;if(['medic','refugee'].includes(id)){part(arm,'box',M.cloth,0,-.27,.18,.22,.2,.14);part(arm,'box',M.blue,0,-.27,.26,.12,.04,.015);if(id==='medic')part(arm,'box',M.blue,0,-.27,.27,.04,.12,.015);}else if(['surveyor','geologist','engineer'].includes(id)){part(arm,'cylinder',M.cloth,0,-.16,.2,.07,.3,.07,0,0,Math.PI/2);part(arm,'box',M.gold,0,-.2,.24,.17,.06,.04);}else if(['merchant','carrier','explorer'].includes(id))part(g,'box',M.wood,.25,.46,-.17,.2,.3,.3);else if(id==='sailor')part(g,'box',M.blue,0,.97,0,.27,.08,.2);else if(id==='warden'){part(arm,'box',M.wood,0,.15,.1,.03,1.1,.03);part(arm,'cone',M.iron,0,.76,.1,.05,.17,.05);}else if(id==='diplomat')part(arm,'box',M.cloth,0,-.17,.2,.23,.02,.25);}

function applyEquipment(g,level,M){if(characterEquipment(g,level,M,part))return;const person=g.userData.joints?.body?.visible?g.userData.joints.body:null,mat=M.iron,civil=['settler','surveyor','engineer','medic'].includes(g.userData.type);if(person){if(level>=2)part(person,'box',M.wood,.19,.42,.14,.12,.12,.12);if(level>=3)for(const x of[-.18,.18])part(person,'box',civil?M.cloth:mat,x,.68,.01,.13,.1,.21);if(level>=4)part(person,'cylinder',M.blue,0,.95,0,.14,.04,.14);if(level>=5)part(person,'box',civil?M.wood:M.metal,-.22,.51,.12,.13,.17,.1);if(level>=6)part(person,'box',M.cloth,.18,.6,-.12,.16,.24,.18);if(level>=7)for(const x of[-.18,.18])part(person,'box',M.metal,x,.54,.14,.09,.12,.07);if(level>=8)part(person,'box',M.gold,.13,.85,.12,.09,.07,.08);if(level>=9)part(person,'box',civil?M.cloth:M.iron,0,.56,.105,.27,.24,.055);if(level>=10)part(person,'box',M.gold,0,.59,.15,.1,.12,.03);}else{for(let n=2;n<=level;n++){const horse=g.userData.designId==='packhorse',z=horse?.35-(n-2)*.09:.7-(n-2)*.18,x=horse?.34:n%2?.44:.5,y=horse?.73:.63+(n%3)*.09;part(g,n>=8?'cylinder':'box',n>=8?M.metal:M.blue,x,y,z,n>=8?.09:.15,.12,n>=8?.09:.17);}}}

function styleBuilding(g,id,M){if(id==='sylvan')for(const x of[-.8,.8])part(g,'ball',M.leaf,x,.8,-.4,.28,.36,.3);if(id==='stonekin')for(const x of[-.7,.7])part(g,'rock',M.cliff,x,.3,0,.34,.55,.4);if(id==='thalass')for(const x of[-.7,.7])part(g,'cylinder',M.wood,x,.25,.6,.06,.6,.06);if(id==='synthetic')for(const x of[-.6,.6])part(g,'box',M.metal,x,1,0,.18,.3,.24);if(id==='astral')part(g,'ring',M.glow,0,1.7,0,.7,.7,.7,Math.PI/2);}
